arguments.command:
python - <<'PY'
from openpyxl import load_workbook
import re
from pathlib import Path
for p in [*Path('Planning').glob('*.xlsx'),*Path('Queue').glob('*.xlsx'),Path('DER_Program_Contact_Directory.xlsx'),*Path('Screening').glob('Existing*.xlsx')]:
 print('\n',p)
 for s in load_workbook(p,data_only=True,read_only=True).worksheets:
  print(s.title,s.max_row,s.max_column)
  for i,r in enumerate(s.values,1):
   t=' '.join(str(x) for x in r if x is not None)
   if i < 5 or re.search('ALN-108|Elderpine|Northline|Halloway|Grantham',t,re.I) or ('map' in p.name.lower() and '108' in t) or 'Read' in s.title or 'Front' in s.title: print(i,r)
PY

